    c=connect(); rows=c.execute('SELECT emoji,user_id FROM reactions WHERE message_id=? ORDER BY emoji',(mid,)).fetchall(); c.close(); d={}
    for r in rows:d.setdefault(r['emoji'],[]).append(r['user_id'])
    return [{'emoji':e,'count':len(v),'user_ids':v} for e,v in d.items()]
